#include <iostream>

int main() {
    // Define and initialize the loop control variable
    unsigned int counter{1};

    // Loop-continuation condition checks if counter <= 10
    while (counter <= 10) {
        std::cout << counter << ' ';
        ++counter; // Increment control variable
    }

    std::cout << '\n';
    return 0;
}

#include <iostream>

int main() {
    // for loop encapsulates initialization, condition, and increment in the header
    for (unsigned int counter{1}; counter <= 10; ++counter) {
        std::cout << counter << ' ';
    }

    std::cout << '\n';
    return 0;
}
